import {escapeHtml as e} from '../shared/utils.js?v=0.18.0';
import {request} from './engine.js?v=0.18.0';
const f=n=>Number(n).toFixed(1);
export function capacityPanel(s,p){const c=p.capacity;if(!c)return `<section class="capacity-panel"><h2>Earlier value-only run</h2><p>Your original accounting is preserved. Replay with capacity to see the core work displaced by exception obligations.</p><button class="button" id="finite-replay">Start a replay with capacity</button></section>`;const done=s.quarter===6;return `<section class="capacity-panel"><div class="bar"><div><p class="eyebrow">THE SAME PEOPLE DO BOTH KINDS OF WORK</p><h2>${done?'Last settled quarter':'What fits this quarter?'}</h2></div>${!done?`<label>Q${s.quarter+1} capacity (effort-days)<input id="budget" type="number" min="0" max="100" step=".5" value="${c.budget}"></label>`:`<strong>${f(c.budget)} days available</strong>`}</div><div class="capacity-bar" role="img" aria-label="${f(c.maintenance)} days upkeep, ${f(c.setup+c.retirement)} changes and exit, ${f(c.coreDone)} core work, ${f(c.spare)} spare; budget ${f(c.budget)}."><span class="upkeep" style="flex:${c.maintenance}"></span><span class="changes" style="flex:${c.setup+c.retirement}"></span><span class="core" style="flex:${c.coreDone}"></span><span class="spare" style="flex:${c.spare}"></span></div><div class="capacity-key"><span>Upkeep <b>${f(c.maintenance)}</b></span><span>Setup / exit <b>${f(c.setup+c.retirement)}</b></span><span>Core work <b>${f(c.coreDone)}</b></span><span>Spare <b>${f(c.spare)}</b></span></div>${!c.feasible?`<p class="capacity-warning"><b>${f(c.shortfall)} days over budget.</b> This proposal cannot settle. Change its requests or explicitly increase this quarter’s budget; no value or progress is earned until it fits.</p>`:`<p class="capacity-insight">${f(c.coreRemaining)} days of available core work remain waiting. Without this quarter’s upkeep, <b>${f(c.maintenanceDisplaced)} more days</b> could fit, holding setup and retirement fixed.</p>`}<details id="core-details"><summary>Which core work moves or waits?</summary><p>Arrival order; work can be partly completed. This is a local comparison with the same starting backlog, not a replay of earlier quarters.</p><p class="table-scroll-hint">Scroll sideways through the results ↔.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable effort and work table"><table><thead><tr><th>Core work</th><th>Waiting before</th><th>Done ${done?'in Q'+(s.quarter):'if settled'}</th><th>Still waiting</th></tr></thead><tbody>${c.work.map(j=>`<tr><th>${e(j.title)}</th><td>${f(j.remainingBefore)}</td><td>${f(j.delivered)}</td><td>${f(j.remainingAfter)}</td></tr>`).join('')||'<tr><td colspan="4">No core work available yet.</td></tr>'}</tbody></table></div></details><details id="effort-trace"><summary>Trace the exception effort</summary><p class="table-scroll-hint">Scroll sideways through the results ↔.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable effort and work table"><table><thead><tr><th>Request</th><th>Setup</th><th>Upkeep</th><th>Exit</th></tr></thead><tbody>${c.items.filter(x=>x.setup+x.maintenance+x.retirement>0).map(x=>`<tr><th>${e(request(x.id).name)}</th><td>${f(x.setup)}</td><td>${f(x.maintenance)}</td><td>${f(x.retirement)}</td></tr>`).join('')}${c.pairs.map(x=>`<tr><th>${e(request(x.a).name)} × ${e(request(x.b).name)}</th><td>—</td><td>${f(x.effort)}</td><td>—</td></tr>`).join('')}</tbody></table></div></details></section>`;}
export function capacitySettings(s){if(!s.capacity)return '';const c=s.capacity,done=s.quarter===6;return `<details class="effort-settings" id="capacity-settings"><summary>Effort and core work assumptions</summary><p>Days are independent estimates, not converted from value points. Editing a revealed request is allowed until its first settlement. Later requests retain their estimates until revealed.</p><p class="table-scroll-hint">Scroll sideways through the results ↔.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable effort and work table"><table class="effort-inputs"><thead><tr><th>Revealed request</th><th>Tailored setup</th><th>Standardise</th><th>Upkeep / q</th><th>Retire</th></tr></thead><tbody>${s.entries.map(x=>`<tr><th>${e(request(x.id).name)}</th>${['setup','standard','maintenance','retire'].map(k=>`<td><input aria-label="${e(request(x.id).name)} ${k} effort-days" data-effort-id="${x.id}" data-effort-field="${k}" type="number" min="0" max="50" step=".25" value="${c.effort[x.id][k]}" ${x.status!=='pending'||done?'disabled':''}></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="effort-parameters"><label>Extra upkeep per quarter of age (days)<input id="effort-aging" type="number" min="0" max="3" step=".05" value="${c.aging}" ${s.quarter?'disabled':''}></label><label>Overlapping pair upkeep (days)<input id="effort-pair" type="number" min="0" max="6" step=".1" value="${c.pair}" ${s.quarter?'disabled':''}></label></div><p>Standard upkeep is 40% of the estimate and does not age. Standards reduce pair effort to one third and save up to 1.5 days of related tailored setup. Whole-quarter choices assume an implementation is available for that quarter; no partially finished exception earns benefit.</p><h3>Known core work arriving each quarter</h3><p>These planned items are known from the start, unlike new exception requests. Edit before Q1 settles.</p><div class="core-inputs">${c.jobs.map(j=>`<div><span>Q${j.arrive+1}</span><label class="sr-only" for="job-${j.id}">Core work arriving Q${j.arrive+1}</label><input id="job-${j.id}" data-job="${j.id}" data-job-field="title" value="${e(j.title)}" maxlength="300" ${s.quarter?'disabled':''}><label>Effort-days<input aria-label="Effort for ${e(j.title)}" data-job="${j.id}" data-job-field="effort" type="number" min=".5" max="100" step=".5" value="${j.effort}" ${s.quarter?'disabled':''}></label></div>`).join('')}</div><h3>Capacity by quarter</h3><p>Past budgets are locked. Future budgets can change explicitly; policy replays use this same schedule.</p><div class="budgets">${c.budgets.map((v,q)=>`<label>Q${q+1}<input aria-label="Quarter ${q+1} capacity" data-budget="${q}" type="number" min="0" max="100" step=".5" value="${v}" ${q<s.quarter?'disabled':''}></label>`).join('')}</div></details>`;}
